//! Accessible hierarchical UEFI Setup owned by Accessible Windows.
//!
//! The firmware stage must remain operable without sight. This module therefore
//! keeps the whole Setup on the keyboard, emits deterministic proof markers for
//! every visible item and state transition, and never times out after the user has
//! interacted. Fixed speech phrases are generated by scripts/gen-speech.ps1 and
//! are wired into HDA separately so text-only navigation is never mistaken for
//! completed nonvisual speech.

use core::time::Duration;

use uefi::boot;
use uefi::proto::console::text::{Key, ScanCode};
use uefi::runtime::{self, ResetType};
use uefi::system;
use uefi::Status;

use crate::sound;

const IDLE_WINDOW: Duration = Duration::from_secs(3);
const POLL_INTERVAL: Duration = Duration::from_millis(50);
const CUE_MOVE_HZ: u32 = 660;
const CUE_ENTER_HZ: u32 = 784;
const CUE_BACK_HZ: u32 = 523;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Page {
    Root,
    Main,
    SystemInformation,
    Advanced,
    CpuConfiguration,
    Boot,
    BootPriorities,
    Security,
    SecureBoot,
    SaveExit,
    ConfirmRestart,
    ConfirmShutdown,
}

#[derive(Clone, Copy, Debug)]
enum Action {
    Enter(Page),
    Back,
    ContinueBoot,
    Restart,
    Shutdown,
    FirmwareSetupPending,
    Noop,
}

#[derive(Clone, Copy)]
struct MenuItem {
    label: &'static str,
    action: Action,
}

